export const medicineDisciplines:MedDiscipline[]=[{"slug":"anatomia-humana","title":"Anatomia Humana","cycle":"basico","years":"1º–2º","description":"Estruturas e relações do corpo humano","image":"/images/anatomia/file_000000003a44820e809657f89b0aa613.webp","topics":[{"id":"anatomia-humana-1","name":"Terminologia anatômica","theory":"A posição anatômica padroniza a descrição do corpo em pé, face anterior, palmas voltadas para a frente. Termos como medial, lateral, proximal e distal são relacionais e evitam ambiguidade entre profissionais.","example":"O coração é medial aos pulmões e o punho é distal ao cotovelo.","question":"Qual termo indica proximidade do plano mediano?","options":["Medial","Distal","Superior"],"correct":0,"feedback":"Medial. A posição anatômica padroniza a descrição do corpo em pé, face anterior, palmas voltadas para a frente. Termos como medial, lateral, proximal e distal são relacionais e evitam ambiguidade entre profissionais.","cycle":"basico"},{"id":"anatomia-humana-2","name":"Planos e eixos corporais","theory":"O plano sagital divide direita e esquerda; o frontal separa anterior e posterior; o transversal distingue superior e inferior. Os eixos permitem descrever movimentos articulados a esses planos.","example":"Uma tomografia axial mostra cortes no plano transversal do corpo.","question":"Qual plano separa anterior de posterior?","options":["Sagital","Frontal","Transversal"],"correct":1,"feedback":"Frontal. O plano sagital divide direita e esquerda; o frontal separa anterior e posterior; o transversal distingue superior e inferior. Os eixos permitem descrever movimentos articulados a esses planos.","cycle":"basico"},{"id":"anatomia-humana-3","name":"Sistema esquelético","theory":"O esqueleto axial compreende crânio, coluna e caixa torácica; o apendicular inclui cinturas e membros. Ossos atuam na sustentação, proteção, hematopoiese e reserva mineral, em interação com músculos e articulações.","example":"As costelas protegem estruturas torácicas e participam da mecânica respiratória.","question":"Qual estrutura pertence ao esqueleto axial?","options":["Fêmur","Escápula","Esterno"],"correct":2,"feedback":"Esterno. O esqueleto axial compreende crânio, coluna e caixa torácica; o apendicular inclui cinturas e membros. Ossos atuam na sustentação, proteção, hematopoiese e reserva mineral, em interação com músculos e articulações.","cycle":"basico"},{"id":"anatomia-humana-4","name":"Articulações e movimentos","theory":"Articulações sinoviais possuem cavidade articular, cápsula e superfícies com cartilagem; o movimento depende de sua forma e de ligamentos e músculos. Flexão e extensão alteram ângulos entre segmentos.","example":"O cotovelo permite sobretudo flexão e extensão, enquanto o ombro possui maior amplitude.","question":"Qual componente é típico de articulação sinovial?","options":["Cavidade articular","Disco intervertebral em todas","Ausência de cápsula"],"correct":0,"feedback":"Cavidade articular. Articulações sinoviais possuem cavidade articular, cápsula e superfícies com cartilagem; o movimento depende de sua forma e de ligamentos e músculos. Flexão e extensão alteram ângulos entre segmentos.","cycle":"basico"},{"id":"anatomia-humana-5","name":"Músculos e compartimentos","theory":"Músculos esqueléticos originam movimentos por contração coordenada. A organização em compartimentos, vascularização e inervação orienta a compreensão de déficit motor e a localização anatômica de estruturas.","example":"Lesão de nervo periférico pode comprometer músculos de um compartimento específico.","question":"Qual tecido realiza contração voluntária principal?","options":["Epitélio de revestimento","Músculo esquelético","Cartilagem hialina"],"correct":1,"feedback":"Músculo esquelético. Músculos esqueléticos originam movimentos por contração coordenada. A organização em compartimentos, vascularização e inervação orienta a compreensão de déficit motor e a localização anatômica de estruturas.","cycle":"basico"},{"id":"anatomia-humana-6","name":"Anatomia topográfica do tórax","theory":"O mediastino contém coração, grandes vasos, traqueia e outras estruturas; os pulmões ocupam as cavidades pleurais. Relações topográficas são fundamentais para interpretar imagens, auscultar e reconhecer estruturas.","example":"Uma imagem torácica mostra o coração no mediastino, entre as cavidades pleurais.","question":"Onde se localiza o coração?","options":["Cavidade pleural direita","Cavidade peritoneal","Mediastino"],"correct":2,"feedback":"Mediastino. O mediastino contém coração, grandes vasos, traqueia e outras estruturas; os pulmões ocupam as cavidades pleurais. Relações topográficas são fundamentais para interpretar imagens, auscultar e reconhecer estruturas.","cycle":"basico"}]},{"slug":"histologia","title":"Histologia","cycle":"basico","years":"1º–2º","description":"Tecidos, lâminas e organização microscópica","image":"/images/biologia/histologia.webp","topics":[{"id":"histologia-1","name":"Epitélios de revestimento","theory":"Epitélios revestem superfícies e cavidades, apresentam células justapostas, polaridade e membrana basal, sendo avasculares. O formato celular e o número de camadas relacionam-se com proteção, absorção e secreção.","example":"O epitélio simples pavimentoso favorece trocas rápidas nos alvéolos pulmonares.","question":"Qual característica é típica dos epitélios?","options":["Avascularidade","Rica vascularização entre células","Matriz extracelular abundante"],"correct":0,"feedback":"Avascularidade. Epitélios revestem superfícies e cavidades, apresentam células justapostas, polaridade e membrana basal, sendo avasculares. O formato celular e o número de camadas relacionam-se com proteção, absorção e secreção.","cycle":"basico"},{"id":"histologia-2","name":"Tecido conjuntivo","theory":"O tecido conjuntivo apresenta células distribuídas em matriz extracelular com fibras colágenas, elásticas e substância fundamental. Sua composição varia de acordo com sustentação, reparo, defesa e transporte.","example":"Tendões têm predomínio de fibras colágenas organizadas para resistir à tração.","question":"Qual componente caracteriza especialmente o tecido conjuntivo?","options":["Ausência total de fibras","Matriz extracelular","Junções epiteliais apenas"],"correct":1,"feedback":"Matriz extracelular. O tecido conjuntivo apresenta células distribuídas em matriz extracelular com fibras colágenas, elásticas e substância fundamental. Sua composição varia de acordo com sustentação, reparo, defesa e transporte.","cycle":"basico"},{"id":"histologia-3","name":"Cartilagem e osso","theory":"A cartilagem contém condrócitos em matriz resistente e não possui vasos próprios; o osso apresenta matriz mineralizada, osteócitos e remodelação dinâmica. Ambos oferecem suporte estrutural em diferentes condições.","example":"Cartilagem articular reduz atrito em superfícies sinoviais, enquanto o osso suporta carga.","question":"Qual tecido é normalmente avascular?","options":["Osso compacto","Medula óssea","Cartilagem"],"correct":2,"feedback":"Cartilagem. A cartilagem contém condrócitos em matriz resistente e não possui vasos próprios; o osso apresenta matriz mineralizada, osteócitos e remodelação dinâmica. Ambos oferecem suporte estrutural em diferentes condições.","cycle":"basico"},{"id":"histologia-4","name":"Tecido muscular","theory":"Músculo esquelético é estriado e voluntário; o cardíaco é estriado, possui discos intercalares e atividade involuntária; o liso não é estriado e atua em vísceras e vasos.","example":"Histologia do miocárdio mostra fibras ramificadas e discos intercalares.","question":"Qual característica indica músculo cardíaco?","options":["Discos intercalares","Células multinucleadas longas sem ramificações como regra","Ausência de estriação"],"correct":0,"feedback":"Discos intercalares. Músculo esquelético é estriado e voluntário; o cardíaco é estriado, possui discos intercalares e atividade involuntária; o liso não é estriado e atua em vísceras e vasos.","cycle":"basico"},{"id":"histologia-5","name":"Tecido nervoso","theory":"Neurônios recebem e transmitem sinais; células da glia participam do suporte metabólico, isolamento e defesa. Bainhas de mielina aceleram condução em muitos axônios, e a organização varia entre sistema central e periférico.","example":"Oligodendrócitos formam mielina no sistema nervoso central.","question":"Qual célula mieliniza axônios no sistema nervoso central?","options":["Hemácia","Oligodendrócito","Fibroblasto"],"correct":1,"feedback":"Oligodendrócito. Neurônios recebem e transmitem sinais; células da glia participam do suporte metabólico, isolamento e defesa. Bainhas de mielina aceleram condução em muitos axônios, e a organização varia entre sistema central e periférico.","cycle":"basico"},{"id":"histologia-6","name":"Sangue e hematopoiese","theory":"Sangue é tecido conjuntivo com plasma e elementos celulares. Hemácias transportam gases; leucócitos atuam na defesa; plaquetas ajudam na hemostasia. Na vida pós-natal, células sanguíneas são produzidas principalmente na medula óssea.","example":"Hemograma separa hemoglobina, leucócitos e plaquetas para avaliação clínica.","question":"Qual elemento participa diretamente da hemostasia primária?","options":["Hemácias maduras","Adipócitos","Plaquetas"],"correct":2,"feedback":"Plaquetas. Sangue é tecido conjuntivo com plasma e elementos celulares. Hemácias transportam gases; leucócitos atuam na defesa; plaquetas ajudam na hemostasia. Na vida pós-natal, células sanguíneas são produzidas principalmente na medula óssea.","cycle":"basico"}]},{"slug":"embriologia","title":"Embriologia","cycle":"basico","years":"1º–2º","description":"Desenvolvimento humano e bases congênitas","image":"/images/biologia/embriologia.webp","topics":[{"id":"embriologia-1","name":"Gametogênese","theory":"A gametogênese produz gametas haploides por meiose e diferenciação celular, reduzindo o número cromossômico e permitindo sua recomposição na fecundação. A espermatogênese e a ovogênese possuem ritmos próprios.","example":"A união de dois gametas haploides resulta, em geral, em zigoto diploide.","question":"Qual processo reduz a ploidia na formação dos gametas?","options":["Meiose","Mitose somática","Transcrição"],"correct":0,"feedback":"Meiose. A gametogênese produz gametas haploides por meiose e diferenciação celular, reduzindo o número cromossômico e permitindo sua recomposição na fecundação. A espermatogênese e a ovogênese possuem ritmos próprios.","cycle":"basico"},{"id":"embriologia-2","name":"Fecundação e clivagem","theory":"Após reconhecimento e fusão dos gametas, o zigoto inicia divisões mitóticas chamadas clivagem. A sequência forma mórula e blastocisto, com diferenciação inicial entre massa celular interna e trofoblasto.","example":"O blastocisto apresenta cavidade e regiões celulares com destinos embrionários distintos.","question":"Qual estrutura sucede a mórula no desenvolvimento habitual?","options":["Gástrula antes da clivagem","Blastocisto","Placenta madura"],"correct":1,"feedback":"Blastocisto. Após reconhecimento e fusão dos gametas, o zigoto inicia divisões mitóticas chamadas clivagem. A sequência forma mórula e blastocisto, com diferenciação inicial entre massa celular interna e trofoblasto.","cycle":"basico"},{"id":"embriologia-3","name":"Implantação e placenta","theory":"A implantação envolve interação do trofoblasto com o endométrio; a placenta em desenvolvimento permite trocas de gases, nutrientes e metabólitos entre circulações materna e fetal sem mistura direta generalizada do sangue.","example":"Vilosidades coriônicas aumentam superfície de troca placentária.","question":"Qual estrutura está ligada às trocas materno-fetais?","options":["Cristalino","Epífise óssea","Vilosidades coriônicas"],"correct":2,"feedback":"Vilosidades coriônicas. A implantação envolve interação do trofoblasto com o endométrio; a placenta em desenvolvimento permite trocas de gases, nutrientes e metabólitos entre circulações materna e fetal sem mistura direta generalizada do sangue.","cycle":"basico"},{"id":"embriologia-4","name":"Gastrulação e folhetos","theory":"A gastrulação estabelece ectoderma, mesoderma e endoderma, origem de tecidos e órgãos. Conhecer seus derivados ajuda a entender anomalias do desenvolvimento e a integração entre sistemas corporais.","example":"O tubo neural deriva do ectoderma; a musculatura esquelética deriva predominantemente do mesoderma.","question":"Qual folheto origina grande parte da musculatura?","options":["Mesoderma","Endoderma apenas","Trofoblasto"],"correct":0,"feedback":"Mesoderma. A gastrulação estabelece ectoderma, mesoderma e endoderma, origem de tecidos e órgãos. Conhecer seus derivados ajuda a entender anomalias do desenvolvimento e a integração entre sistemas corporais.","cycle":"basico"},{"id":"embriologia-5","name":"Neurulação","theory":"A placa neural ectodérmica dobra-se para formar o tubo neural, precursor do sistema nervoso central. O fechamento do tubo ocorre em etapas específicas do desenvolvimento embrionário.","example":"Alterações no fechamento do tubo neural relacionam-se a defeitos congênitos desse sistema.","question":"Qual estrutura origina o sistema nervoso central?","options":["Saco vitelino","Tubo neural","Âmnio"],"correct":1,"feedback":"Tubo neural. A placa neural ectodérmica dobra-se para formar o tubo neural, precursor do sistema nervoso central. O fechamento do tubo ocorre em etapas específicas do desenvolvimento embrionário.","cycle":"basico"},{"id":"embriologia-6","name":"Organogênese","theory":"A organogênese envolve proliferação, migração, sinalização e diferenciação celular para formação dos órgãos. O desenvolvimento de vários sistemas é simultâneo e interdependente, com períodos de maior sensibilidade a agressões.","example":"A formação do coração embrionário começa antes do amadurecimento de diversos outros órgãos.","question":"Qual processo produz estruturas orgânicas diferenciadas?","options":["Somente calcificação tardia","Apenas implantação","Organogênese"],"correct":2,"feedback":"Organogênese. A organogênese envolve proliferação, migração, sinalização e diferenciação celular para formação dos órgãos. O desenvolvimento de vários sistemas é simultâneo e interdependente, com períodos de maior sensibilidade a agressões.","cycle":"basico"}]},{"slug":"bioquimica","title":"Bioquímica","cycle":"basico","years":"1º–2º","description":"Moléculas, metabolismo e regulação celular","image":"/images/biologia/bioquimica-celular.webp","topics":[{"id":"bioquimica-1","name":"Água, pH e tampões","theory":"O meio aquoso permite interações bioquímicas e participa da regulação ácido-base. Sistemas tampão resistem a mudanças bruscas de pH, enquanto pulmões e rins contribuem para a homeostase em diferentes escalas de tempo.","example":"O sistema bicarbonato atua no equilíbrio ácido-base do líquido extracelular.","question":"Qual sistema é um tampão importante do sangue?","options":["Bicarbonato","Triglicerídeos","Hemoglobina glicosilada como único tampão"],"correct":0,"feedback":"Bicarbonato. O meio aquoso permite interações bioquímicas e participa da regulação ácido-base. Sistemas tampão resistem a mudanças bruscas de pH, enquanto pulmões e rins contribuem para a homeostase em diferentes escalas de tempo.","cycle":"basico"},{"id":"bioquimica-2","name":"Proteínas e enzimas","theory":"Proteínas são cadeias de aminoácidos cuja estrutura determina função. Enzimas diminuem a energia de ativação das reações, mas não alteram o equilíbrio termodinâmico final de uma transformação.","example":"Uma deficiência enzimática pode reduzir a velocidade de uma via metabólica.","question":"O que enzimas geralmente diminuem?","options":["Quantidade de átomos reagentes","Energia de ativação","Temperatura corporal obrigatoriamente"],"correct":1,"feedback":"Energia de ativação. Proteínas são cadeias de aminoácidos cuja estrutura determina função. Enzimas diminuem a energia de ativação das reações, mas não alteram o equilíbrio termodinâmico final de uma transformação.","cycle":"basico"},{"id":"bioquimica-3","name":"Carboidratos e glicólise","theory":"A glicólise converte glicose em piruvato e produz ATP e equivalentes redutores. O destino do piruvato depende de disponibilidade de oxigênio, estado celular e necessidades metabólicas.","example":"Na glicólise, a célula obtém energia mesmo sem participação direta de oxigênio na sequência de reações.","question":"Em que compartimento ocorre a glicólise?","options":["Núcleo","Lúmen do retículo endoplasmático","Citosol"],"correct":2,"feedback":"Citosol. A glicólise converte glicose em piruvato e produz ATP e equivalentes redutores. O destino do piruvato depende de disponibilidade de oxigênio, estado celular e necessidades metabólicas.","cycle":"basico"},{"id":"bioquimica-4","name":"Lipídios e membranas","theory":"Fosfolipídios organizam-se em bicamada com regiões hidrofílicas e hidrofóbicas. Colesterol modula propriedades da membrana; triglicerídeos atuam sobretudo no armazenamento energético.","example":"A bicamada lipídica separa compartimentos e permite regulação da passagem de substâncias.","question":"Que molécula é componente estrutural central da bicamada?","options":["Fosfolipídio","DNA","Glicogênio"],"correct":0,"feedback":"Fosfolipídio. Fosfolipídios organizam-se em bicamada com regiões hidrofílicas e hidrofóbicas. Colesterol modula propriedades da membrana; triglicerídeos atuam sobretudo no armazenamento energético.","cycle":"basico"},{"id":"bioquimica-5","name":"Ciclo do ácido cítrico","theory":"O ciclo do ácido cítrico ocorre principalmente na matriz mitocondrial e oxida grupos acetil, gerando NADH, FADH2 e GTP ou ATP, conectando metabolismo de carboidratos, lipídios e aminoácidos.","example":"NADH produzido no ciclo pode fornecer elétrons à cadeia respiratória.","question":"Onde ocorre a maior parte do ciclo do ácido cítrico?","options":["Citosol","Matriz mitocondrial","Membrana plasmática"],"correct":1,"feedback":"Matriz mitocondrial. O ciclo do ácido cítrico ocorre principalmente na matriz mitocondrial e oxida grupos acetil, gerando NADH, FADH2 e GTP ou ATP, conectando metabolismo de carboidratos, lipídios e aminoácidos.","cycle":"basico"},{"id":"bioquimica-6","name":"Integração metabólica","theory":"Insulina e glucagon coordenam, entre outras funções, armazenamento e mobilização de combustíveis. Estado alimentado e jejum mudam fluxos de glicose, lipídios e aminoácidos conforme o tecido e as reservas corporais.","example":"Após refeição, a ação da insulina favorece captação e armazenamento de nutrientes em diversos tecidos.","question":"Qual hormônio está associado ao estado alimentado?","options":["Glucagon exclusivamente","Melatonina","Insulina"],"correct":2,"feedback":"Insulina. Insulina e glucagon coordenam, entre outras funções, armazenamento e mobilização de combustíveis. Estado alimentado e jejum mudam fluxos de glicose, lipídios e aminoácidos conforme o tecido e as reservas corporais.","cycle":"basico"}]},{"slug":"fisiologia","title":"Fisiologia","cycle":"basico","years":"1º–2º","description":"Funções, mecanismos e homeostase","image":"/images/biologia/fisiologia-humana.webp","topics":[{"id":"fisiologia-1","name":"Homeostase e retroalimentação","theory":"Homeostase mantém variáveis fisiológicas dentro de faixas compatíveis com funcionamento celular. Circuitos de retroalimentação negativa detectam desvios e acionam respostas que tendem a reduzir a alteração.","example":"A elevação da temperatura corporal aciona mecanismos de dissipação de calor.","question":"Qual mecanismo tende a reduzir um desvio fisiológico?","options":["Feedback negativo","Feedback positivo necessariamente","Mutação genética"],"correct":0,"feedback":"Feedback negativo. Homeostase mantém variáveis fisiológicas dentro de faixas compatíveis com funcionamento celular. Circuitos de retroalimentação negativa detectam desvios e acionam respostas que tendem a reduzir a alteração.","cycle":"basico"},{"id":"fisiologia-2","name":"Potenciais de membrana","theory":"Gradientes iônicos e permeabilidade seletiva geram potencial elétrico através da membrana. O potencial de ação depende da abertura coordenada de canais iônicos voltagem-dependentes em células excitáveis.","example":"Em muitos neurônios, canais de sódio contribuem para a fase rápida de despolarização.","question":"Qual íon participa da despolarização rápida neuronal clássica?","options":["Ferro","Sódio","Iodo"],"correct":1,"feedback":"Sódio. Gradientes iônicos e permeabilidade seletiva geram potencial elétrico através da membrana. O potencial de ação depende da abertura coordenada de canais iônicos voltagem-dependentes em células excitáveis.","cycle":"basico"},{"id":"fisiologia-3","name":"Fisiologia cardiovascular","theory":"Débito cardíaco relaciona frequência cardíaca e volume sistólico; pressão arterial depende de múltiplos fatores, incluindo resistência vascular. O acoplamento entre coração e vasos assegura perfusão de tecidos.","example":"Uma mudança na frequência pode modificar débito cardíaco se o volume sistólico se mantiver.","question":"Qual é a relação simplificada do débito cardíaco?","options":["Pressão ÷ glicemia","Volume sistólico + temperatura","Frequência × volume sistólico"],"correct":2,"feedback":"Frequência × volume sistólico. Débito cardíaco relaciona frequência cardíaca e volume sistólico; pressão arterial depende de múltiplos fatores, incluindo resistência vascular. O acoplamento entre coração e vasos assegura perfusão de tecidos.","cycle":"basico"},{"id":"fisiologia-4","name":"Fisiologia respiratória","theory":"Ventilação leva ar aos alvéolos; difusão permite trocas gasosas e perfusão transporta gases no sangue. A relação ventilação-perfusão influencia a eficiência da oxigenação.","example":"Um alvéolo ventilado, mas pouco perfundido, contribui para espaço morto fisiológico.","question":"Qual processo transporta oxigênio dos alvéolos ao sangue?","options":["Difusão","Osteogênese","Coagulação"],"correct":0,"feedback":"Difusão. Ventilação leva ar aos alvéolos; difusão permite trocas gasosas e perfusão transporta gases no sangue. A relação ventilação-perfusão influencia a eficiência da oxigenação.","cycle":"basico"},{"id":"fisiologia-5","name":"Fisiologia renal","theory":"Rins filtram plasma, reabsorvem substâncias úteis, secretam solutos e excretam resíduos. Também participam da regulação de volume, eletrólitos, pressão arterial e equilíbrio ácido-base.","example":"Reabsorção tubular recupera grande parcela da água filtrada pelos glomérulos.","question":"Qual processo recupera substâncias do filtrado?","options":["Secreção exócrina","Reabsorção tubular","Ventilação"],"correct":1,"feedback":"Reabsorção tubular. Rins filtram plasma, reabsorvem substâncias úteis, secretam solutos e excretam resíduos. Também participam da regulação de volume, eletrólitos, pressão arterial e equilíbrio ácido-base.","cycle":"basico"},{"id":"fisiologia-6","name":"Fisiologia endócrina","theory":"Hormônios atuam por receptores em células-alvo e coordenam metabolismo, crescimento, reprodução e adaptação. Eixos hormonais envolvem circuitos de controle e pulsos temporais, dependendo do sistema.","example":"TSH da hipófise participa do controle de hormônios tireoidianos.","question":"Qual característica define ação hormonal?","options":["Atuação apenas no local de síntese","Ausência de regulação","Sinal por receptores específicos"],"correct":2,"feedback":"Sinal por receptores específicos. Hormônios atuam por receptores em células-alvo e coordenam metabolismo, crescimento, reprodução e adaptação. Eixos hormonais envolvem circuitos de controle e pulsos temporais, dependendo do sistema.","cycle":"basico"}]},{"slug":"genetica-medica","title":"Genética Médica","cycle":"basico","years":"1º–2º","description":"Hereditariedade, genoma e investigação genética","image":"/images/trilhas/artwork-17.png","topics":[{"id":"genetica-medica-1","name":"DNA e organização gênica","theory":"O DNA armazena informação em nucleotídeos e organiza genes e regiões regulatórias em cromossomos. Variantes podem alterar sequência codificante, regulação ou processamento, com efeitos diversos e nem sempre patológicos.","example":"Alteração em região promotora pode modificar expressão gênica sem alterar proteína diretamente.","question":"Qual molécula armazena a informação genética celular?","options":["DNA","ATP","Colesterol"],"correct":0,"feedback":"DNA. O DNA armazena informação em nucleotídeos e organiza genes e regiões regulatórias em cromossomos. Variantes podem alterar sequência codificante, regulação ou processamento, com efeitos diversos e nem sempre patológicos.","cycle":"basico"},{"id":"genetica-medica-2","name":"Expressão gênica","theory":"Transcrição gera RNA a partir de DNA e tradução sintetiza proteínas a partir de RNA mensageiro. Diferentes mecanismos regulam quantidade e momento da expressão conforme o tipo celular.","example":"Neurônios e hepatócitos podem expressar genes distintos apesar de compartilharem o mesmo genoma.","question":"Qual processo sintetiza RNA a partir de DNA?","options":["Tradução","Transcrição","Glicólise"],"correct":1,"feedback":"Transcrição. Transcrição gera RNA a partir de DNA e tradução sintetiza proteínas a partir de RNA mensageiro. Diferentes mecanismos regulam quantidade e momento da expressão conforme o tipo celular.","cycle":"basico"},{"id":"genetica-medica-3","name":"Herança autossômica","theory":"Padrões dominantes e recessivos descrevem transmissão de variantes em autossomos, considerando penetrância e expressividade. Um padrão recessivo clássico pode aparecer em filhos de pais sem manifestações clínicas.","example":"Dois portadores heterozigotos de variante autossômica recessiva podem ter filho afetado.","question":"Qual padrão pode envolver pais portadores assintomáticos?","options":["Ligado ao Y exclusivamente","Mitocondrial exclusivamente","Autossômico recessivo"],"correct":2,"feedback":"Autossômico recessivo. Padrões dominantes e recessivos descrevem transmissão de variantes em autossomos, considerando penetrância e expressividade. Um padrão recessivo clássico pode aparecer em filhos de pais sem manifestações clínicas.","cycle":"basico"},{"id":"genetica-medica-4","name":"Cromossomopatias","theory":"Alterações numéricas ou estruturais cromossômicas podem afetar desenvolvimento e função. Cariótipo identifica algumas alterações grandes, enquanto técnicas moleculares detectam alterações de outras escalas.","example":"Trissomia é presença de cópia adicional de um cromossomo.","question":"Como se chama a presença de três cópias de um cromossomo?","options":["Trissomia","Monossomia","Isodisomia sempre"],"correct":0,"feedback":"Trissomia. Alterações numéricas ou estruturais cromossômicas podem afetar desenvolvimento e função. Cariótipo identifica algumas alterações grandes, enquanto técnicas moleculares detectam alterações de outras escalas.","cycle":"basico"},{"id":"genetica-medica-5","name":"Herança multifatorial","theory":"Muitas condições dependem de múltiplas variantes genéticas e fatores ambientais. Risco probabilístico não equivale a diagnóstico certo e deve ser interpretado com histórico familiar e contexto clínico.","example":"Predisposição genética a diabetes tipo 2 interage com fatores ambientais.","question":"Qual modelo considera genes e ambiente?","options":["Monogênico obrigatório","Multifatorial","Somente ambiental"],"correct":1,"feedback":"Multifatorial. Muitas condições dependem de múltiplas variantes genéticas e fatores ambientais. Risco probabilístico não equivale a diagnóstico certo e deve ser interpretado com histórico familiar e contexto clínico.","cycle":"basico"},{"id":"genetica-medica-6","name":"Aconselhamento e ética","theory":"Informações genéticas exigem consentimento informado, confidencialidade, cuidado com resultados incidentais e comunicação clara da incerteza. Testes devem responder perguntas clínicas pertinentes e respeitar autonomia.","example":"Um resultado genético de significado incerto não equivale automaticamente a uma doença.","question":"Qual princípio é essencial ao discutir testes genéticos?","options":["Compartilhar resultados indiscriminadamente","Ignorar incertezas","Consentimento informado"],"correct":2,"feedback":"Consentimento informado. Informações genéticas exigem consentimento informado, confidencialidade, cuidado com resultados incidentais e comunicação clara da incerteza. Testes devem responder perguntas clínicas pertinentes e respeitar autonomia.","cycle":"basico"}]},{"slug":"microbiologia","title":"Microbiologia","cycle":"basico","years":"1º–2º","description":"Agentes infecciosos, microbiota e resistência","image":"/images/biologia/microbiologia.webp","topics":[{"id":"microbiologia-1","name":"Estrutura bacteriana","theory":"Bactérias são organismos procariontes com membrana, ribossomos e DNA sem núcleo membranoso. Parede celular e características de superfície influenciam coloração, resposta imune e certos alvos farmacológicos.","example":"A coloração de Gram ajuda a classificar grupos bacterianos segundo sua parede.","question":"O que é típico das bactérias?","options":["Ausência de núcleo delimitado por membrana","Núcleo com carioteca","Mitocôndrias obrigatórias"],"correct":0,"feedback":"Ausência de núcleo delimitado por membrana. Bactérias são organismos procariontes com membrana, ribossomos e DNA sem núcleo membranoso. Parede celular e características de superfície influenciam coloração, resposta imune e certos alvos farmacológicos.","cycle":"basico"},{"id":"microbiologia-2","name":"Bactérias Gram-positivas e negativas","theory":"Gram-positivas apresentam espessa camada de peptidoglicano; Gram-negativas possuem membrana externa adicional contendo lipopolissacarídeos. A diferenciação é útil, mas não determina sozinha conduta clínica.","example":"LPS de Gram-negativas atua como componente estrutural com potencial inflamatório.","question":"Que estrutura existe na membrana externa de muitas Gram-negativas?","options":["Colágeno tipo I","Lipopolissacarídeo","Hemoglobina"],"correct":1,"feedback":"Lipopolissacarídeo. Gram-positivas apresentam espessa camada de peptidoglicano; Gram-negativas possuem membrana externa adicional contendo lipopolissacarídeos. A diferenciação é útil, mas não determina sozinha conduta clínica.","cycle":"basico"},{"id":"microbiologia-3","name":"Vírus e replicação","theory":"Vírus dependem da maquinaria celular para replicação e possuem genoma de DNA ou RNA e capsídeo, podendo ter envelope. Estratégias de entrada e replicação variam muito entre famílias virais.","example":"Vírus envelopados têm camada lipídica derivada da célula hospedeira.","question":"Qual característica é comum aos vírus?","options":["Metabolismo completo autônomo","Divisão por mitose própria","Dependência de células para replicação"],"correct":2,"feedback":"Dependência de células para replicação. Vírus dependem da maquinaria celular para replicação e possuem genoma de DNA ou RNA e capsídeo, podendo ter envelope. Estratégias de entrada e replicação variam muito entre famílias virais.","cycle":"basico"},{"id":"microbiologia-4","name":"Fungos de interesse médico","theory":"Fungos são eucariontes e incluem leveduras e formas filamentosas. Estrutura celular e adaptação ao hospedeiro influenciam manifestações e diagnóstico, muitas vezes com exames microscópicos e culturas.","example":"Leveduras podem apresentar brotamento na reprodução assexuada.","question":"Qual característica identifica fungos?","options":["Células eucarióticas","Ausência absoluta de membrana","Somente organismos procariontes"],"correct":0,"feedback":"Células eucarióticas. Fungos são eucariontes e incluem leveduras e formas filamentosas. Estrutura celular e adaptação ao hospedeiro influenciam manifestações e diagnóstico, muitas vezes com exames microscópicos e culturas.","cycle":"basico"},{"id":"microbiologia-5","name":"Parasitologia introdutória","theory":"Protozoários e helmintos possuem ciclos de vida específicos, às vezes com hospedeiros intermediários ou vetores. A compreensão da transmissão orienta ações de prevenção e vigilância.","example":"Controle de vetores pode reduzir transmissão de determinadas parasitoses.","question":"Qual fator é essencial para entender transmissão parasitária?","options":["Somente grupo sanguíneo","Ciclo de vida do agente","Somente cor do agente"],"correct":1,"feedback":"Ciclo de vida do agente. Protozoários e helmintos possuem ciclos de vida específicos, às vezes com hospedeiros intermediários ou vetores. A compreensão da transmissão orienta ações de prevenção e vigilância.","cycle":"basico"},{"id":"microbiologia-6","name":"Resistência a antimicrobianos","theory":"Resistência pode decorrer de mutação, seleção e transferência de genes. Uso desnecessário de antimicrobianos aumenta pressão seletiva; o antibiograma ajuda identificar suscetibilidade sob condições laboratoriais padronizadas.","example":"Uso inadequado de antibiótico pode selecionar bactérias resistentes em uma comunidade.","question":"O que pode contribuir para resistência?","options":["Vacinação como causa única","Lavagem de mãos como causa","Pressão seletiva por antimicrobianos"],"correct":2,"feedback":"Pressão seletiva por antimicrobianos. Resistência pode decorrer de mutação, seleção e transferência de genes. Uso desnecessário de antimicrobianos aumenta pressão seletiva; o antibiograma ajuda identificar suscetibilidade sob condições laboratoriais padronizadas.","cycle":"basico"}]},{"slug":"imunologia","title":"Imunologia","cycle":"basico","years":"1º–2º","description":"Defesas, inflamação e respostas adaptativas","image":"/images/anatomia/file_00000000d45c820e8a621a9f2061cf0c.webp","topics":[{"id":"imunologia-1","name":"Imunidade inata","theory":"A imunidade inata responde rapidamente a padrões de perigo e microrganismos por barreiras, fagócitos, complemento e sinais inflamatórios. Não depende do reconhecimento clonotípico específico de antígeno.","example":"Macrófagos podem fagocitar microrganismos e liberar mediadores inflamatórios.","question":"Qual célula integra a imunidade inata?","options":["Macrófago","Hemácia madura","Osteócito"],"correct":0,"feedback":"Macrófago. A imunidade inata responde rapidamente a padrões de perigo e microrganismos por barreiras, fagócitos, complemento e sinais inflamatórios. Não depende do reconhecimento clonotípico específico de antígeno.","cycle":"basico"},{"id":"imunologia-2","name":"Apresentação de antígenos","theory":"Células apresentadoras processam antígenos e exibem peptídeos associados a MHC para linfócitos T. MHC I e II participam de vias de apresentação diferentes e ajudam a orientar respostas celulares.","example":"Células dendríticas conectam respostas inatas à ativação de linfócitos T.","question":"Qual molécula participa da apresentação de peptídeos?","options":["Hemoglobina","MHC","Colágeno"],"correct":1,"feedback":"MHC. Células apresentadoras processam antígenos e exibem peptídeos associados a MHC para linfócitos T. MHC I e II participam de vias de apresentação diferentes e ajudam a orientar respostas celulares.","cycle":"basico"},{"id":"imunologia-3","name":"Linfócitos e anticorpos","theory":"Linfócitos B podem produzir anticorpos após ativação e diferenciação em plasmócitos. Linfócitos T auxiliares coordenam respostas e T citotóxicos reconhecem determinadas células-alvo.","example":"Anticorpos podem neutralizar agentes ou facilitar sua eliminação.","question":"Qual célula secreta grandes quantidades de anticorpos?","options":["Neutrófilo","Hemácia","Plasmócito"],"correct":2,"feedback":"Plasmócito. Linfócitos B podem produzir anticorpos após ativação e diferenciação em plasmócitos. Linfócitos T auxiliares coordenam respostas e T citotóxicos reconhecem determinadas células-alvo.","cycle":"basico"},{"id":"imunologia-4","name":"Memória imunológica","theory":"A resposta adaptativa pode gerar células de memória capazes de responder de forma mais rápida em exposições posteriores. Vacinas buscam induzir proteção sem os riscos associados à doença natural.","example":"Reexposição a antígeno conhecido pode produzir resposta mais rápida e intensa.","question":"Qual fenômeno fundamenta boa parte da vacinação?","options":["Memória imunológica","Ausência de linfócitos","Destruição de toda microbiota"],"correct":0,"feedback":"Memória imunológica. A resposta adaptativa pode gerar células de memória capazes de responder de forma mais rápida em exposições posteriores. Vacinas buscam induzir proteção sem os riscos associados à doença natural.","cycle":"basico"},{"id":"imunologia-5","name":"Hipersensibilidade","theory":"Reações de hipersensibilidade podem envolver anticorpos, imunocomplexos ou células T, sendo agrupadas em padrões mecanísticos. A classificação ajuda entender fenótipos, mas diagnósticos clínicos exigem contexto e avaliação.","example":"Reações alérgicas imediatas podem envolver IgE e mastócitos.","question":"Qual imunoglobulina está associada a alergia imediata clássica?","options":["IgD exclusivamente","IgE","IgG4 obrigatoriamente"],"correct":1,"feedback":"IgE. Reações de hipersensibilidade podem envolver anticorpos, imunocomplexos ou células T, sendo agrupadas em padrões mecanísticos. A classificação ajuda entender fenótipos, mas diagnósticos clínicos exigem contexto e avaliação.","cycle":"basico"},{"id":"imunologia-6","name":"Autoimunidade e tolerância","theory":"Mecanismos de tolerância limitam respostas contra componentes próprios. Sua perda pode favorecer processos autoimunes, com participação variável de fatores genéticos, ambientais e imunológicos.","example":"Doenças autoimunes podem comprometer órgãos específicos ou vários sistemas.","question":"Qual mecanismo previne reatividade indevida ao próprio organismo?","options":["Hipertermia","Glicólise","Tolerância imunológica"],"correct":2,"feedback":"Tolerância imunológica. Mecanismos de tolerância limitam respostas contra componentes próprios. Sua perda pode favorecer processos autoimunes, com participação variável de fatores genéticos, ambientais e imunológicos.","cycle":"basico"}]},{"slug":"patologia","title":"Patologia","cycle":"clinico","years":"2º–3º","description":"Processos de lesão, reparo e doença","image":"/images/biologia/citologia-avancada.webp","topics":[{"id":"patologia-1","name":"Adaptação e lesão celular","theory":"Células respondem a estímulos por hipertrofia, hiperplasia, atrofia e metaplasia. Quando agressões excedem capacidade de adaptação, podem ocorrer lesões reversíveis ou morte celular, com padrões distintos.","example":"Hipertrofia pode ocorrer em músculos expostos a maior demanda de trabalho.","question":"Qual adaptação representa aumento do tamanho celular?","options":["Hipertrofia","Atrofia","Necrose"],"correct":0,"feedback":"Hipertrofia. Células respondem a estímulos por hipertrofia, hiperplasia, atrofia e metaplasia. Quando agressões excedem capacidade de adaptação, podem ocorrer lesões reversíveis ou morte celular, com padrões distintos.","cycle":"clinico"},{"id":"patologia-2","name":"Necrose e apoptose","theory":"Necrose costuma resultar de agressão com perda de integridade de membranas e resposta inflamatória; apoptose é processo regulado de morte celular com fragmentação ordenada e, em geral, menor inflamação local.","example":"Células com dano irreparável podem ser eliminadas por vias apoptóticas.","question":"Qual processo costuma ser regulado e ordenado?","options":["Necrose sempre","Apoptose","Calcificação"],"correct":1,"feedback":"Apoptose. Necrose costuma resultar de agressão com perda de integridade de membranas e resposta inflamatória; apoptose é processo regulado de morte celular com fragmentação ordenada e, em geral, menor inflamação local.","cycle":"clinico"},{"id":"patologia-3","name":"Inflamação aguda e crônica","theory":"Inflamação envolve alterações vasculares e recrutamento de células de defesa. Respostas agudas costumam ter neutrófilos; processos crônicos podem envolver macrófagos, linfócitos e alterações teciduais persistentes.","example":"Uma lesão recente com grande número de neutrófilos sugere processo inflamatório agudo.","question":"Qual célula é frequente na inflamação aguda?","options":["Condrócito","Osteoblasto","Neutrófilo"],"correct":2,"feedback":"Neutrófilo. Inflamação envolve alterações vasculares e recrutamento de células de defesa. Respostas agudas costumam ter neutrófilos; processos crônicos podem envolver macrófagos, linfócitos e alterações teciduais persistentes.","cycle":"clinico"},{"id":"patologia-4","name":"Cicatrização e reparo","theory":"Reparo pode ocorrer por regeneração celular e formação de tecido fibroso. A resposta depende do tipo de lesão, matriz, suprimento sanguíneo e condições locais.","example":"Fibroblastos produzem matriz rica em colágeno durante formação de cicatriz.","question":"Qual célula participa da síntese de colágeno cicatricial?","options":["Fibroblasto","Hemácia","Célula beta pancreática"],"correct":0,"feedback":"Fibroblasto. Reparo pode ocorrer por regeneração celular e formação de tecido fibroso. A resposta depende do tipo de lesão, matriz, suprimento sanguíneo e condições locais.","cycle":"clinico"},{"id":"patologia-5","name":"Distúrbios hemodinâmicos","theory":"Edema, congestão, trombose e embolia descrevem mecanismos diferentes de alteração de fluidos e fluxo vascular. A interpretação requer ligar a lesão ao sistema circulatório e ao contexto clínico.","example":"Trombo formado em vaso pode obstruir fluxo e, em certas situações, embolizar.","question":"Qual termo define massa intravascular formada durante a vida?","options":["Cálculo renal","Trombo","Abscesso"],"correct":1,"feedback":"Trombo. Edema, congestão, trombose e embolia descrevem mecanismos diferentes de alteração de fluidos e fluxo vascular. A interpretação requer ligar a lesão ao sistema circulatório e ao contexto clínico.","cycle":"clinico"},{"id":"patologia-6","name":"Neoplasia","theory":"Neoplasias envolvem crescimento celular autônomo e alterações moleculares progressivas; tumores benignos e malignos diferem quanto a invasão e potencial metastático. Classificação depende de critérios histológicos e clínicos.","example":"Invasão de tecidos adjacentes é característica que favorece diagnóstico de malignidade.","question":"Qual propriedade caracteriza malignidade?","options":["Cápsula em todos os casos","Ausência de alterações genéticas","Capacidade de invasão"],"correct":2,"feedback":"Capacidade de invasão. Neoplasias envolvem crescimento celular autônomo e alterações moleculares progressivas; tumores benignos e malignos diferem quanto a invasão e potencial metastático. Classificação depende de critérios histológicos e clínicos.","cycle":"clinico"}]},{"slug":"farmacologia","title":"Farmacologia","cycle":"clinico","years":"2º–3º","description":"Mecanismos, cinética e segurança de medicamentos","image":"/images/quimica/quimica-organica.webp","topics":[{"id":"farmacologia-1","name":"Farmacocinética: absorção","theory":"Farmacocinética descreve absorção, distribuição, metabolismo e excreção. Biodisponibilidade representa fração da dose que alcança circulação sistêmica inalterada e varia com via e características do fármaco.","example":"Administração intravenosa tem biodisponibilidade de referência igual a 100%.","question":"Qual processo integra farmacocinética?","options":["Absorção","Ligação ao receptor como único mecanismo","Transcrição de DNA"],"correct":0,"feedback":"Absorção. Farmacocinética descreve absorção, distribuição, metabolismo e excreção. Biodisponibilidade representa fração da dose que alcança circulação sistêmica inalterada e varia com via e características do fármaco.","cycle":"clinico"},{"id":"farmacologia-2","name":"Distribuição e ligação proteica","theory":"Após alcançar sangue, um fármaco distribui-se conforme perfusão, afinidade tecidual, barreiras e ligação a proteínas plasmáticas. A fração livre costuma ser importante para efeito farmacológico e eliminação.","example":"Fármacos muito ligados à albumina podem ter menor fração plasmática livre.","question":"Qual fração pode alcançar receptores diretamente com mais facilidade?","options":["Fração irreversivelmente ligada","Fração livre","Fármaco degradado"],"correct":1,"feedback":"Fração livre. Após alcançar sangue, um fármaco distribui-se conforme perfusão, afinidade tecidual, barreiras e ligação a proteínas plasmáticas. A fração livre costuma ser importante para efeito farmacológico e eliminação.","cycle":"clinico"},{"id":"farmacologia-3","name":"Metabolismo e eliminação","theory":"Fígado e rins participam da depuração de muitos fármacos, com grande variabilidade entre substâncias. Metabolismo não necessariamente inativa um composto; alguns metabólitos possuem atividade própria.","example":"Insuficiência renal pode alterar exposição a medicamentos excretados pelos rins.","question":"Qual órgão é central na excreção de muitos fármacos?","options":["Baço","Pele exclusivamente","Rim"],"correct":2,"feedback":"Rim. Fígado e rins participam da depuração de muitos fármacos, com grande variabilidade entre substâncias. Metabolismo não necessariamente inativa um composto; alguns metabólitos possuem atividade própria.","cycle":"clinico"},{"id":"farmacologia-4","name":"Farmacodinâmica e receptores","theory":"Farmacodinâmica estuda como fármacos produzem efeitos. Agonistas ativam receptores; antagonistas podem impedir sua ativação. Eficácia e potência representam propriedades diferentes.","example":"Um antagonista competitivo pode reduzir resposta a determinado agonista em um receptor.","question":"Qual agente ativa diretamente o receptor?","options":["Agonista","Antagonista puro","Excipiente"],"correct":0,"feedback":"Agonista. Farmacodinâmica estuda como fármacos produzem efeitos. Agonistas ativam receptores; antagonistas podem impedir sua ativação. Eficácia e potência representam propriedades diferentes.","cycle":"clinico"},{"id":"farmacologia-5","name":"Interações medicamentosas","theory":"Interações farmacológicas podem alterar exposição ou resposta por mecanismos cinéticos e dinâmicos. A importância clínica depende de dose, estado do paciente, comorbidades e monitorização.","example":"Inibição de uma enzima metabolizadora pode elevar concentração de outro medicamento.","question":"Qual efeito pode ocorrer ao inibir metabolismo de um fármaco?","options":["Desaparecimento universal da resposta","Aumento de exposição","Ausência absoluta de efeitos"],"correct":1,"feedback":"Aumento de exposição. Interações farmacológicas podem alterar exposição ou resposta por mecanismos cinéticos e dinâmicos. A importância clínica depende de dose, estado do paciente, comorbidades e monitorização.","cycle":"clinico"},{"id":"farmacologia-6","name":"Segurança e farmacovigilância","theory":"Farmacovigilância identifica, avalia e previne eventos adversos e problemas relacionados a medicamentos. Dose, indicação, contraindicações e perfil clínico influenciam decisão terapêutica e requerem supervisão profissional.","example":"Notificar suspeita de evento adverso contribui para identificar riscos pouco frequentes.","question":"Qual prática integra farmacovigilância?","options":["Automedicação indiscriminada","Omissão de efeitos","Notificação de eventos adversos"],"correct":2,"feedback":"Notificação de eventos adversos. Farmacovigilância identifica, avalia e previne eventos adversos e problemas relacionados a medicamentos. Dose, indicação, contraindicações e perfil clínico influenciam decisão terapêutica e requerem supervisão profissional.","cycle":"clinico"}]},{"slug":"semiologia","title":"Semiologia","cycle":"clinico","years":"3º–4º","description":"Anamnese, exame e raciocínio clínico","image":"/images/anatomia/file_000000001358820e9257c0d143190e34.webp","topics":[{"id":"semiologia-1","name":"Anamnese centrada na pessoa","theory":"Anamnese reúne queixa, história do problema, antecedentes, medicamentos, hábitos e contexto social, com escuta ativa e linguagem respeitosa. Perguntas abertas inicialmente evitam induzir respostas e favorecem compreensão da experiência.","example":"“O que mais preocupa você nesse sintoma?” explora perspectiva do paciente.","question":"Qual estratégia favorece uma anamnese inicial adequada?","options":["Pergunta aberta","Interromper a primeira resposta","Pressupor diagnóstico"],"correct":0,"feedback":"Pergunta aberta. Anamnese reúne queixa, história do problema, antecedentes, medicamentos, hábitos e contexto social, com escuta ativa e linguagem respeitosa. Perguntas abertas inicialmente evitam induzir respostas e favorecem compreensão da experiência.","cycle":"clinico"},{"id":"semiologia-2","name":"Organização do exame físico","theory":"Exame físico sistematiza inspeção, palpação, percussão e ausculta conforme órgão e necessidade, respeitando consentimento, privacidade e medidas de biossegurança. Achados devem ser descritos de forma objetiva.","example":"Registrar localização e características de um achado é mais útil que apenas dizer “normal”.","question":"Qual prática deve anteceder um exame físico?","options":["Ignorar privacidade","Explicar procedimento e obter consentimento","Evitar higiene das mãos"],"correct":1,"feedback":"Explicar procedimento e obter consentimento. Exame físico sistematiza inspeção, palpação, percussão e ausculta conforme órgão e necessidade, respeitando consentimento, privacidade e medidas de biossegurança. Achados devem ser descritos de forma objetiva.","cycle":"clinico"},{"id":"semiologia-3","name":"Sinais vitais","theory":"Pressão arterial, frequência cardíaca, frequência respiratória, temperatura e saturação fornecem pistas relevantes, mas sua interpretação requer técnica correta, contexto e tendências ao longo do tempo.","example":"Medição de pressão com manguito inadequado pode distorcer resultado.","question":"O que melhora a confiabilidade de sinais vitais?","options":["Uma única medida sem contexto","Ignorar equipamento","Técnica de medição correta"],"correct":2,"feedback":"Técnica de medição correta. Pressão arterial, frequência cardíaca, frequência respiratória, temperatura e saturação fornecem pistas relevantes, mas sua interpretação requer técnica correta, contexto e tendências ao longo do tempo.","cycle":"clinico"},{"id":"semiologia-4","name":"Exame cardiovascular","theory":"Inspeção, palpação de pulsos, avaliação de perfusão e ausculta cardíaca podem orientar hipóteses. Sopros e outros ruídos exigem localização, tempo, intensidade e correlação clínica.","example":"Um sopro é descrito segundo fase do ciclo cardíaco e ponto de ausculta.","question":"Qual dado compõe descrição de sopro?","options":["Momento no ciclo cardíaco","Cor dos cabelos","Altura isolada"],"correct":0,"feedback":"Momento no ciclo cardíaco. Inspeção, palpação de pulsos, avaliação de perfusão e ausculta cardíaca podem orientar hipóteses. Sopros e outros ruídos exigem localização, tempo, intensidade e correlação clínica.","cycle":"clinico"},{"id":"semiologia-5","name":"Exame respiratório","theory":"Observação do padrão ventilatório, expansibilidade torácica, percussão e ausculta ajudam localizar alterações. Ruídos adventícios devem ser descritos, não automaticamente vinculados a doença sem integração com história clínica.","example":"Crepitações podem ocorrer em diferentes processos respiratórios e não definem sozinhas etiologia.","question":"Qual etapa integra o exame pulmonar?","options":["Fundoscopia obrigatória","Ausculta","Avaliação dentária"],"correct":1,"feedback":"Ausculta. Observação do padrão ventilatório, expansibilidade torácica, percussão e ausculta ajudam localizar alterações. Ruídos adventícios devem ser descritos, não automaticamente vinculados a doença sem integração com história clínica.","cycle":"clinico"},{"id":"semiologia-6","name":"Exame abdominal","theory":"A avaliação abdominal combina inspeção, ausculta, percussão e palpação suave a profunda conforme contexto. Dor, defesa e outros sinais requerem avaliação adequada e respeito ao desconforto.","example":"Em muitos roteiros, a ausculta abdominal precede palpação para evitar modificar ruídos.","question":"Qual etapa costuma anteceder palpação no exame abdominal clássico?","options":["Percussão de joelhos","Oftalmoscopia","Ausculta"],"correct":2,"feedback":"Ausculta. A avaliação abdominal combina inspeção, ausculta, percussão e palpação suave a profunda conforme contexto. Dor, defesa e outros sinais requerem avaliação adequada e respeito ao desconforto.","cycle":"clinico"}]},{"slug":"clinica-medica","title":"Clínica Médica","cycle":"clinico","years":"3º–6º","description":"Integração de mecanismos, exames e condições clínicas","image":"/images/anatomia/file_00000000e320820e8f2e5b55ab6dbf81.webp","topics":[{"id":"clinica-medica-1","name":"Raciocínio clínico","theory":"Raciocínio clínico integra queixas, sinais, probabilidades pré-teste e resultados de exames para construir e revisar hipóteses. Diferenciar achados específicos de inespecíficos reduz conclusões precipitadas.","example":"Uma alteração laboratorial isolada não substitui avaliação clínica contextualizada.","question":"Qual prática é central ao raciocínio clínico?","options":["Integrar história, exame e testes","Interpretar apenas um marcador","Ignorar probabilidades"],"correct":0,"feedback":"Integrar história, exame e testes. Raciocínio clínico integra queixas, sinais, probabilidades pré-teste e resultados de exames para construir e revisar hipóteses. Diferenciar achados específicos de inespecíficos reduz conclusões precipitadas.","cycle":"clinico"},{"id":"clinica-medica-2","name":"Hipertensão arterial: fundamentos","theory":"Pressão arterial depende de débito cardíaco e resistência vascular, com influência renal, neural e hormonal. Diagnóstico e acompanhamento exigem medidas adequadas, confirmação quando apropriado e avaliação global de risco.","example":"Uma medida elevada isolada em ambiente estressante não confirma, por si só, hipertensão crônica.","question":"O que é necessário para avaliar adequadamente a pressão?","options":["Apenas uma leitura sem revisão","Medidas com técnica e contexto","Só frequência cardíaca"],"correct":1,"feedback":"Medidas com técnica e contexto. Pressão arterial depende de débito cardíaco e resistência vascular, com influência renal, neural e hormonal. Diagnóstico e acompanhamento exigem medidas adequadas, confirmação quando apropriado e avaliação global de risco.","cycle":"clinico"},{"id":"clinica-medica-3","name":"Diabetes: fisiopatologia","theory":"Diabetes mellitus envolve hiperglicemia sustentada por deficiência de secreção de insulina, resistência à sua ação ou ambos. Mecanismos e tratamento diferem por tipo e situação clínica, e acompanhamento visa reduzir complicações.","example":"Resistência insulínica tem papel importante na fisiopatologia frequente do diabetes tipo 2.","question":"Qual hormônio é central na regulação da glicemia?","options":["Calcitonina","Prolactina","Insulina"],"correct":2,"feedback":"Insulina. Diabetes mellitus envolve hiperglicemia sustentada por deficiência de secreção de insulina, resistência à sua ação ou ambos. Mecanismos e tratamento diferem por tipo e situação clínica, e acompanhamento visa reduzir complicações.","cycle":"clinico"},{"id":"clinica-medica-4","name":"Asma: mecanismos","theory":"Asma envolve inflamação e variabilidade da limitação ao fluxo aéreo, com sintomas que podem oscilar. Avaliação usa história, função pulmonar quando possível e análise de gravidade, sem reduzir diagnóstico a um único sintoma.","example":"Chiado pode ocorrer na asma, mas não é exclusivo dela.","question":"Qual característica se associa à asma?","options":["Limitação variável do fluxo aéreo","Obstrução anatômica fixa obrigatória","Ausência de inflamação"],"correct":0,"feedback":"Limitação variável do fluxo aéreo. Asma envolve inflamação e variabilidade da limitação ao fluxo aéreo, com sintomas que podem oscilar. Avaliação usa história, função pulmonar quando possível e análise de gravidade, sem reduzir diagnóstico a um único sintoma.","cycle":"clinico"},{"id":"clinica-medica-5","name":"Insuficiência cardíaca","theory":"Insuficiência cardíaca é síndrome associada a alterações estruturais ou funcionais cardíacas, com manifestações por redução da capacidade de enchimento/ejeção e elevação de pressões, exigindo avaliação clínica e complementar.","example":"Dispneia e edema podem ser manifestações, mas também possuem outras causas.","question":"Qual órgão é central na insuficiência cardíaca?","options":["Baço","Coração","Pâncreas"],"correct":1,"feedback":"Coração. Insuficiência cardíaca é síndrome associada a alterações estruturais ou funcionais cardíacas, com manifestações por redução da capacidade de enchimento/ejeção e elevação de pressões, exigindo avaliação clínica e complementar.","cycle":"clinico"},{"id":"clinica-medica-6","name":"Função renal e lesão","theory":"A avaliação renal envolve filtração glomerular, exame de urina, eletrólitos e contexto temporal. Lesão renal aguda e doença renal crônica se diferenciam por duração e critérios clínico-laboratoriais.","example":"Creatinina deve ser interpretada com tendência temporal e características do paciente.","question":"Qual dado ajuda diferenciar lesão aguda de crônica?","options":["Apenas cor da urina","Um sintoma inespecífico","Evolução ao longo do tempo"],"correct":2,"feedback":"Evolução ao longo do tempo. A avaliação renal envolve filtração glomerular, exame de urina, eletrólitos e contexto temporal. Lesão renal aguda e doença renal crônica se diferenciam por duração e critérios clínico-laboratoriais.","cycle":"clinico"}]},{"slug":"cirurgia","title":"Cirurgia","cycle":"internato","years":"3º–6º","description":"Princípios cirúrgicos, perioperatórios e segurança","image":"/images/anatomia/file_00000000cb94820e8f572fbc208c18b3.webp","topics":[{"id":"cirurgia-1","name":"Assepsia e prevenção de infecção","theory":"Medidas de assepsia, antissepsia e esterilização reduzem contaminação em procedimentos. A seleção e execução dependem da natureza do procedimento, protocolos e biossegurança.","example":"Higiene das mãos é medida básica de prevenção de infecções associadas à assistência.","question":"Qual medida é essencial antes de procedimentos?","options":["Higiene adequada das mãos","Reutilização de material contaminado","Ausência de antissepsia"],"correct":0,"feedback":"Higiene adequada das mãos. Medidas de assepsia, antissepsia e esterilização reduzem contaminação em procedimentos. A seleção e execução dependem da natureza do procedimento, protocolos e biossegurança.","cycle":"internato"},{"id":"cirurgia-2","name":"Avaliação pré-operatória","theory":"Avaliação pré-operatória considera condições clínicas, indicação cirúrgica, riscos, medicamentos e possibilidade de otimização. O processo inclui comunicação clara, consentimento e planejamento em equipe.","example":"Comorbidades podem exigir ajuste do plano perioperatório e avaliação multiprofissional.","question":"Qual elemento integra avaliação pré-operatória?","options":["Ignorar uso de medicamentos","Avaliar riscos e comorbidades","Substituir consentimento por presunção"],"correct":1,"feedback":"Avaliar riscos e comorbidades. Avaliação pré-operatória considera condições clínicas, indicação cirúrgica, riscos, medicamentos e possibilidade de otimização. O processo inclui comunicação clara, consentimento e planejamento em equipe.","cycle":"internato"},{"id":"cirurgia-3","name":"Anatomia cirúrgica","theory":"Reconhecimento de planos, vasos, nervos e relações anatômicas reduz risco de lesões durante procedimentos. A técnica deve respeitar variabilidade anatômica e indicação, e não pode ser aprendida apenas por texto.","example":"Uma estrutura vascular pode variar de posição entre pacientes e regiões anatômicas.","question":"Qual fator torna anatomia aplicada relevante?","options":["Igualdade absoluta entre corpos","Ausência de vasos em regiões cirúrgicas","Variabilidade e relações anatômicas"],"correct":2,"feedback":"Variabilidade e relações anatômicas. Reconhecimento de planos, vasos, nervos e relações anatômicas reduz risco de lesões durante procedimentos. A técnica deve respeitar variabilidade anatômica e indicação, e não pode ser aprendida apenas por texto.","cycle":"internato"},{"id":"cirurgia-4","name":"Cicatrização de feridas","theory":"Reparo de feridas passa por fases sobrepostas de hemostasia, inflamação, proliferação e remodelamento. Perfusão, infecção e doenças sistêmicas podem alterar o tempo e a qualidade de cicatrização.","example":"Diabetes descompensado pode prejudicar cicatrização por vários mecanismos.","question":"Qual fase geralmente precede proliferação tecidual?","options":["Inflamação","Remodelamento final em todos os casos","Calcificação exclusiva"],"correct":0,"feedback":"Inflamação. Reparo de feridas passa por fases sobrepostas de hemostasia, inflamação, proliferação e remodelamento. Perfusão, infecção e doenças sistêmicas podem alterar o tempo e a qualidade de cicatrização.","cycle":"internato"},{"id":"cirurgia-5","name":"Complicações pós-operatórias","theory":"Eventos pós-operatórios podem envolver sistemas respiratório, cardiovascular, infeccioso e tromboembólico. Prevenção requer avaliação de risco, medidas protocoladas e monitoramento adequado.","example":"Mobilização e prevenção de trombose são consideradas conforme risco do paciente.","question":"Qual ação integra segurança pós-operatória?","options":["Ignorar sinais de complicação","Monitoramento e prevenção dirigida por risco","Suspender observação"],"correct":1,"feedback":"Monitoramento e prevenção dirigida por risco. Eventos pós-operatórios podem envolver sistemas respiratório, cardiovascular, infeccioso e tromboembólico. Prevenção requer avaliação de risco, medidas protocoladas e monitoramento adequado.","cycle":"internato"},{"id":"cirurgia-6","name":"Abdome agudo: abordagem","theory":"Abdome agudo é síndrome potencialmente grave que requer avaliação da estabilidade, história, exame e decisão sobre necessidade de exames e intervenção. Causas inflamatórias, obstrutivas, perfurativas e vasculares exigem diferenciação.","example":"Dor abdominal súbita intensa com instabilidade exige avaliação médica imediata.","question":"Qual é prioridade diante de instabilidade com abdome agudo?","options":["Aguardar evolução sem avaliação","Assumir uma única causa","Avaliar e estabilizar o paciente"],"correct":2,"feedback":"Avaliar e estabilizar o paciente. Abdome agudo é síndrome potencialmente grave que requer avaliação da estabilidade, história, exame e decisão sobre necessidade de exames e intervenção. Causas inflamatórias, obstrutivas, perfurativas e vasculares exigem diferenciação.","cycle":"internato"}]},{"slug":"pediatria","title":"Pediatria","cycle":"internato","years":"3º–6º","description":"Crescimento, desenvolvimento e cuidado da criança","image":"/images/biologia/introducao-biologia.webp","topics":[{"id":"pediatria-1","name":"Crescimento infantil","theory":"Crescimento deve ser acompanhado longitudinalmente com curvas apropriadas, considerando idade, sexo, medidas e condições de saúde. Uma medida isolada é menos informativa que trajetória coerente ao longo do tempo.","example":"Queda persistente de percentis de crescimento pede avaliação contextualizada.","question":"Qual informação melhora avaliação do crescimento?","options":["Série de medidas no tempo","Uma fotografia","Apenas idade da mãe"],"correct":0,"feedback":"Série de medidas no tempo. Crescimento deve ser acompanhado longitudinalmente com curvas apropriadas, considerando idade, sexo, medidas e condições de saúde. Uma medida isolada é menos informativa que trajetória coerente ao longo do tempo.","cycle":"internato"},{"id":"pediatria-2","name":"Marcos do desenvolvimento","theory":"Desenvolvimento engloba domínios motor, linguagem, social e cognitivo; a sequência e a variação devem ser interpretadas considerando idade corrigida quando indicada e contexto familiar.","example":"Avaliar linguagem e interação social é tão importante quanto observar marcha.","question":"Qual domínio integra desenvolvimento infantil?","options":["Somente estatura","Linguagem","Somente pressão arterial"],"correct":1,"feedback":"Linguagem. Desenvolvimento engloba domínios motor, linguagem, social e cognitivo; a sequência e a variação devem ser interpretadas considerando idade corrigida quando indicada e contexto familiar.","cycle":"internato"},{"id":"pediatria-3","name":"Imunização","theory":"Vacinas estimulam resposta imune e reduzem risco de doenças infecciosas. Calendários dependem da idade e condições específicas, devendo seguir recomendações oficiais atualizadas, não um calendário fixo inventado na aula.","example":"O calendário do PNI é referência para imunização no Brasil.","question":"Qual instituição publica calendário nacional de vacinação?","options":["Banco Central","IBGE exclusivamente","Ministério da Saúde"],"correct":2,"feedback":"Ministério da Saúde. Vacinas estimulam resposta imune e reduzem risco de doenças infecciosas. Calendários dependem da idade e condições específicas, devendo seguir recomendações oficiais atualizadas, não um calendário fixo inventado na aula.","cycle":"internato"},{"id":"pediatria-4","name":"Sinais de gravidade pediátrica","theory":"Sinais de alerta podem incluir alterações de consciência, dificuldade respiratória importante, desidratação grave e instabilidade circulatória. Reconhecimento precoce e encaminhamento adequado são essenciais.","example":"Uma criança com rebaixamento de consciência requer atendimento imediato.","question":"Qual achado exige avaliação urgente?","options":["Alteração importante de consciência","Brincadeira habitual","Apetite normal"],"correct":0,"feedback":"Alteração importante de consciência. Sinais de alerta podem incluir alterações de consciência, dificuldade respiratória importante, desidratação grave e instabilidade circulatória. Reconhecimento precoce e encaminhamento adequado são essenciais.","cycle":"internato"},{"id":"pediatria-5","name":"Hidratação e equilíbrio hídrico","theory":"Crianças podem ter maior vulnerabilidade a alterações hidroeletrolíticas em doenças agudas. Avaliação considera ingestão, perdas, diurese e sinais clínicos, com tratamento individualizado por profissional habilitado.","example":"Diarreia com redução de diurese exige avaliação do estado de hidratação.","question":"Qual dado ajuda avaliar hidratação?","options":["Cor das roupas","Diurese","Altura do responsável"],"correct":1,"feedback":"Diurese. Crianças podem ter maior vulnerabilidade a alterações hidroeletrolíticas em doenças agudas. Avaliação considera ingestão, perdas, diurese e sinais clínicos, com tratamento individualizado por profissional habilitado.","cycle":"internato"},{"id":"pediatria-6","name":"Neonatologia introdutória","theory":"O período neonatal exige atenção à transição cardiorrespiratória, alimentação, triagens e avaliação clínica. Parâmetros de normalidade e protocolos diferem do cuidado de adultos.","example":"A transição do nascimento envolve expansão pulmonar e mudanças da circulação.","question":"Qual sistema sofre adaptação importante no nascimento?","options":["Apenas sistema ósseo","Somente cabelos","Cardiorrespiratório"],"correct":2,"feedback":"Cardiorrespiratório. O período neonatal exige atenção à transição cardiorrespiratória, alimentação, triagens e avaliação clínica. Parâmetros de normalidade e protocolos diferem do cuidado de adultos.","cycle":"internato"}]},{"slug":"ginecologia-obstetricia","title":"Ginecologia e Obstetrícia","cycle":"internato","years":"3º–6º","description":"Saúde reprodutiva, gestação e cuidado integral","image":"/images/biologia/reproducao-humana.webp","topics":[{"id":"ginecologia-obstetricia-1","name":"Ciclo menstrual","theory":"O ciclo reprodutivo envolve interação entre hipotálamo, hipófise, ovários e endométrio. Variações de FSH, LH, estradiol e progesterona participam da maturação folicular, ovulação e mudanças endometriais.","example":"O pico de LH está associado à ovulação em ciclos ovulatórios típicos.","question":"Qual hormônio tem pico pré-ovulatório clássico?","options":["LH","TSH","Calcitonina"],"correct":0,"feedback":"LH. O ciclo reprodutivo envolve interação entre hipotálamo, hipófise, ovários e endométrio. Variações de FSH, LH, estradiol e progesterona participam da maturação folicular, ovulação e mudanças endometriais.","cycle":"internato"},{"id":"ginecologia-obstetricia-2","name":"Anamnese ginecológica","theory":"A consulta ginecológica integra queixas, histórico menstrual e sexual relevante, antecedentes, rastreamento e preferências da pessoa. Privacidade, consentimento, linguagem inclusiva e ausência de julgamento são indispensáveis.","example":"Exame íntimo deve depender de indicação, explicação e consentimento.","question":"Qual princípio é central ao cuidado ginecológico?","options":["Exame sem explicação","Consentimento informado","Exclusão de autonomia"],"correct":1,"feedback":"Consentimento informado. A consulta ginecológica integra queixas, histórico menstrual e sexual relevante, antecedentes, rastreamento e preferências da pessoa. Privacidade, consentimento, linguagem inclusiva e ausência de julgamento são indispensáveis.","cycle":"internato"},{"id":"ginecologia-obstetricia-3","name":"Pré-natal","theory":"Cuidado pré-natal acompanha saúde gestacional, identifica fatores de risco e promove intervenções preventivas. Calendário de consultas, exames e imunizações depende de diretrizes atuais e condições individuais.","example":"Avaliar pressão e evolução gestacional em consultas contribui para identificação de riscos.","question":"Qual objetivo do pré-natal?","options":["Substituir parto hospitalar por aplicativo","Eliminar avaliação clínica","Acompanhamento materno-fetal e prevenção"],"correct":2,"feedback":"Acompanhamento materno-fetal e prevenção. Cuidado pré-natal acompanha saúde gestacional, identifica fatores de risco e promove intervenções preventivas. Calendário de consultas, exames e imunizações depende de diretrizes atuais e condições individuais.","cycle":"internato"},{"id":"ginecologia-obstetricia-4","name":"Fisiologia da gestação","theory":"Na gestação ocorrem adaptações cardiovasculares, respiratórias, renais e endócrinas para sustentar desenvolvimento fetal. A compreensão dessas mudanças ajuda distinguir achados fisiológicos de sinais de alerta.","example":"O volume plasmático tende a aumentar ao longo de uma gestação habitual.","question":"Qual adaptação é comum na gestação?","options":["Aumento do volume plasmático","Fim da perfusão uterina","Ausência de mudanças hormonais"],"correct":0,"feedback":"Aumento do volume plasmático. Na gestação ocorrem adaptações cardiovasculares, respiratórias, renais e endócrinas para sustentar desenvolvimento fetal. A compreensão dessas mudanças ajuda distinguir achados fisiológicos de sinais de alerta.","cycle":"internato"},{"id":"ginecologia-obstetricia-5","name":"Trabalho de parto","theory":"O trabalho de parto envolve dinâmica uterina, modificações cervicais e progressão fetal, com grande variabilidade individual. Monitorização e decisões devem considerar evidências, segurança e autonomia da pessoa gestante.","example":"A dilatação cervical é uma das informações acompanhadas na evolução do parto.","question":"Qual processo faz parte do trabalho de parto?","options":["Digestão de proteínas","Modificação cervical","Ossificação permanente"],"correct":1,"feedback":"Modificação cervical. O trabalho de parto envolve dinâmica uterina, modificações cervicais e progressão fetal, com grande variabilidade individual. Monitorização e decisões devem considerar evidências, segurança e autonomia da pessoa gestante.","cycle":"internato"},{"id":"ginecologia-obstetricia-6","name":"Contracepção e direitos","theory":"Métodos contraceptivos diferem em mecanismo, eficácia, efeitos e adequação. Escolha compartilhada exige informação de qualidade, preferência individual, avaliação de contraindicações e proteção contra ISTs quando pertinente.","example":"Preservativos contribuem para reduzir risco de transmissão de diversas ISTs.","question":"Qual abordagem é adequada na escolha contraceptiva?","options":["Método único para todas as pessoas","Ausência de explicação","Decisão informada e compartilhada"],"correct":2,"feedback":"Decisão informada e compartilhada. Métodos contraceptivos diferem em mecanismo, eficácia, efeitos e adequação. Escolha compartilhada exige informação de qualidade, preferência individual, avaliação de contraindicações e proteção contra ISTs quando pertinente.","cycle":"internato"}]},{"slug":"neurologia","title":"Neurologia","cycle":"internato","years":"3º–6º","description":"Sistema nervoso, exame e condições neurológicas","image":"/images/anatomia/file_000000009438820e8a4af99003b59158.webp","topics":[{"id":"neurologia-1","name":"Organização do sistema nervoso","theory":"Sistema nervoso central inclui encéfalo e medula espinhal; o periférico compreende nervos e gânglios. Vias motoras e sensitivas apresentam padrões anatômicos úteis para localização de lesões.","example":"Déficit focal pode indicar envolvimento de determinadas regiões centrais ou nervos periféricos.","question":"Qual estrutura pertence ao sistema nervoso central?","options":["Medula espinhal","Nervo ulnar","Gânglio sensitivo periférico"],"correct":0,"feedback":"Medula espinhal. Sistema nervoso central inclui encéfalo e medula espinhal; o periférico compreende nervos e gânglios. Vias motoras e sensitivas apresentam padrões anatômicos úteis para localização de lesões.","cycle":"internato"},{"id":"neurologia-2","name":"Exame neurológico","theory":"Exame neurológico combina estado mental, nervos cranianos, força, tônus, reflexos, sensibilidade, coordenação e marcha. A interpretação exige comparar padrão e lateralidade dos achados.","example":"Fraqueza de um hemicorpo requer correlação com outras alterações neurológicas.","question":"Qual componente integra exame neurológico?","options":["Exclusivamente ausculta cardíaca","Avaliação de reflexos","Somente temperatura axilar"],"correct":1,"feedback":"Avaliação de reflexos. Exame neurológico combina estado mental, nervos cranianos, força, tônus, reflexos, sensibilidade, coordenação e marcha. A interpretação exige comparar padrão e lateralidade dos achados.","cycle":"internato"},{"id":"neurologia-3","name":"Acidente vascular cerebral","theory":"AVC decorre de interrupção do fluxo ou hemorragia cerebral e é emergência tempo-dependente. Reconhecimento rápido de déficit súbito e ativação de atendimento são mais importantes do que tentar classificar por conta própria.","example":"Assimetria facial e fraqueza súbita podem indicar AVC e demandam socorro imediato.","question":"Qual característica exige atenção em suspeita de AVC?","options":["Crescimento lento de unhas","Espasmo leve isolado crônico","Déficit neurológico súbito"],"correct":2,"feedback":"Déficit neurológico súbito. AVC decorre de interrupção do fluxo ou hemorragia cerebral e é emergência tempo-dependente. Reconhecimento rápido de déficit súbito e ativação de atendimento são mais importantes do que tentar classificar por conta própria.","cycle":"internato"},{"id":"neurologia-4","name":"Cefaleias e sinais de alarme","theory":"Cefaleias têm causas primárias e secundárias; início súbito intenso, déficits focais ou alterações de consciência são exemplos de sinais que necessitam avaliação urgente. O diagnóstico integra história e exame.","example":"Cefaleia abrupta e muito intensa não deve ser rotulada automaticamente como enxaqueca.","question":"Qual achado é sinal de alerta?","options":["Início súbito muito intenso","Dor típica habitual sem mudanças","Melhora habitual com repouso"],"correct":0,"feedback":"Início súbito muito intenso. Cefaleias têm causas primárias e secundárias; início súbito intenso, déficits focais ou alterações de consciência são exemplos de sinais que necessitam avaliação urgente. O diagnóstico integra história e exame.","cycle":"internato"},{"id":"neurologia-5","name":"Crises epilépticas","theory":"Crise epiléptica é manifestação transitória de atividade elétrica neuronal anormal; epilepsia é condição definida por critérios próprios e não equivale automaticamente a uma crise isolada. A semiologia ajuda classificar eventos.","example":"Evento com alteração de consciência e movimentos involuntários pode exigir investigação diferenciada.","question":"Uma única crise determina epilepsia automaticamente?","options":["Sim, em todos os casos","Não, exige critérios e avaliação","Sim, sem excluir outras causas"],"correct":1,"feedback":"Não, exige critérios e avaliação. Crise epiléptica é manifestação transitória de atividade elétrica neuronal anormal; epilepsia é condição definida por critérios próprios e não equivale automaticamente a uma crise isolada. A semiologia ajuda classificar eventos.","cycle":"internato"},{"id":"neurologia-6","name":"Neuropatias periféricas","theory":"Lesões de nervos periféricos podem produzir déficits sensitivos, motores ou autonômicos em distribuições características. Localização anatômica e contexto ajudam diferenciar de condições centrais e musculares.","example":"Dormência limitada ao território de um nervo pode sugerir comprometimento periférico.","question":"Qual padrão favorece hipótese de neuropatia focal?","options":["Afecção simultânea de todos os órgãos","Ausência total de sinais","Déficit em território de nervo"],"correct":2,"feedback":"Déficit em território de nervo. Lesões de nervos periféricos podem produzir déficits sensitivos, motores ou autonômicos em distribuições características. Localização anatômica e contexto ajudam diferenciar de condições centrais e musculares.","cycle":"internato"}]},{"slug":"saude-coletiva","title":"Saúde Coletiva","cycle":"basico","years":"1º–6º","description":"SUS, epidemiologia, prevenção e políticas públicas","image":"/images/biologia/introducao-biologia.webp","topics":[{"id":"saude-coletiva-1","name":"Princípios do SUS","theory":"O Sistema Único de Saúde tem princípios de universalidade, integralidade e equidade, com organização por redes e níveis de atenção. A prática médica deve compreender território, vínculo e responsabilidades coletivas.","example":"A atenção primária coordena parte relevante do cuidado longitudinal no SUS.","question":"Qual princípio determina acesso universal aos serviços de saúde?","options":["Universalidade","Exclusividade por renda","Pagamento obrigatório como regra"],"correct":0,"feedback":"Universalidade. O Sistema Único de Saúde tem princípios de universalidade, integralidade e equidade, com organização por redes e níveis de atenção. A prática médica deve compreender território, vínculo e responsabilidades coletivas.","cycle":"basico"},{"id":"saude-coletiva-2","name":"Atenção primária à saúde","theory":"A APS atua na promoção, prevenção, cuidado de condições comuns e coordenação de encaminhamentos. A continuidade do vínculo e o conhecimento da comunidade são centrais para cuidado contextualizado.","example":"Acompanhamento de pessoas com condições crônicas pode ser coordenado na unidade básica.","question":"Qual característica da APS é importante?","options":["Atendimento somente hospitalar","Longitudinalidade","Exclusão de ações preventivas"],"correct":1,"feedback":"Longitudinalidade. A APS atua na promoção, prevenção, cuidado de condições comuns e coordenação de encaminhamentos. A continuidade do vínculo e o conhecimento da comunidade são centrais para cuidado contextualizado.","cycle":"basico"},{"id":"saude-coletiva-3","name":"Incidência e prevalência","theory":"Incidência mede ocorrência de casos novos em período e população definidos; prevalência expressa casos existentes em determinado momento ou intervalo. Confundir indicadores compromete interpretação epidemiológica.","example":"Um surto pode elevar incidência mesmo quando prevalência previamente era baixa.","question":"Qual indicador se refere a casos novos?","options":["Prevalência","Letalidade","Incidência"],"correct":2,"feedback":"Incidência. Incidência mede ocorrência de casos novos em período e população definidos; prevalência expressa casos existentes em determinado momento ou intervalo. Confundir indicadores compromete interpretação epidemiológica.","cycle":"basico"},{"id":"saude-coletiva-4","name":"Sensibilidade e especificidade","theory":"Sensibilidade expressa capacidade do teste identificar positivos entre pessoas com a condição; especificidade identifica negativos entre quem não tem a condição. Valores preditivos também dependem da prevalência.","example":"Teste sensível tende a produzir menos falsos negativos, conforme o ponto de corte.","question":"Qual métrica mede proporção de verdadeiros positivos?","options":["Sensibilidade","Especificidade","Risco relativo"],"correct":0,"feedback":"Sensibilidade. Sensibilidade expressa capacidade do teste identificar positivos entre pessoas com a condição; especificidade identifica negativos entre quem não tem a condição. Valores preditivos também dependem da prevalência.","cycle":"basico"},{"id":"saude-coletiva-5","name":"Prevenção e promoção","theory":"Promoção da saúde melhora condições que favorecem bem-estar; prevenção pode ser primária, secundária ou terciária. Intervenções coletivas devem considerar determinantes sociais e desigualdades.","example":"Vacinação é exemplo de prevenção primária; rastreamento adequado pode ser prevenção secundária.","question":"Qual ação exemplifica prevenção primária?","options":["Reabilitação após sequela","Vacinação","Tratamento de complicação tardia"],"correct":1,"feedback":"Vacinação. Promoção da saúde melhora condições que favorecem bem-estar; prevenção pode ser primária, secundária ou terciária. Intervenções coletivas devem considerar determinantes sociais e desigualdades.","cycle":"basico"},{"id":"saude-coletiva-6","name":"Bioética e evidências","theory":"Autonomia, beneficência, não maleficência e justiça ajudam estruturar decisões. Medicina baseada em evidências integra pesquisas, experiência clínica e valores e preferências das pessoas atendidas.","example":"Uma decisão compartilhada discute benefícios, riscos e preferências do paciente.","question":"Qual elemento deve participar da decisão clínica?","options":["Somente hábito do serviço","Exclusão de evidências","Preferências da pessoa"],"correct":2,"feedback":"Preferências da pessoa. Autonomia, beneficência, não maleficência e justiça ajudam estruturar decisões. Medicina baseada em evidências integra pesquisas, experiência clínica e valores e preferências das pessoas atendidas.","cycle":"basico"}]},{"slug":"urgencia-emergencia","title":"Urgência e Emergência","cycle":"internato","years":"4º–6º","description":"Avaliação inicial e reconhecimento de situações críticas","image":"/images/anatomia/file_000000004ad8820eb8dc26b5cdc9dfe1.webp","topics":[{"id":"urgencia-emergencia-1","name":"Avaliação primária ABCDE","theory":"ABCDE organiza avaliação inicial de pacientes potencialmente graves: via aérea, respiração, circulação, estado neurológico e exposição, com intervenção por equipes treinadas de acordo com protocolos locais.","example":"Comprometimento de via aérea exige atenção prioritária durante avaliação inicial.","question":"Qual elemento corresponde à letra A do ABCDE?","options":["Via aérea","Abdome","Ausculta cardíaca exclusiva"],"correct":0,"feedback":"Via aérea. ABCDE organiza avaliação inicial de pacientes potencialmente graves: via aérea, respiração, circulação, estado neurológico e exposição, com intervenção por equipes treinadas de acordo com protocolos locais.","cycle":"internato"},{"id":"urgencia-emergencia-2","name":"Ressuscitação cardiopulmonar","theory":"RCP é resposta a parada cardiorrespiratória e depende de protocolos atualizados, capacitação e acionamento rápido do sistema de emergência. Reconhecimento precoce e desfibrilação quando indicada são fatores fundamentais.","example":"Diante de pessoa inconsciente sem respiração normal, chamar ajuda e iniciar medidas de emergência conforme treinamento é crucial.","question":"Qual medida acompanha suspeita de parada cardíaca?","options":["Aguardar indefinidamente","Acionar imediatamente a emergência","Dar medicamento por conta própria"],"correct":1,"feedback":"Acionar imediatamente a emergência. RCP é resposta a parada cardiorrespiratória e depende de protocolos atualizados, capacitação e acionamento rápido do sistema de emergência. Reconhecimento precoce e desfibrilação quando indicada são fatores fundamentais.","cycle":"internato"},{"id":"urgencia-emergencia-3","name":"Choque circulatório","theory":"Choque representa perfusão tecidual inadequada por diferentes mecanismos, como hipovolemia, falha de bomba, obstrução ou vasodilatação. Reconhecer sinais de hipoperfusão e suas causas exige avaliação urgente.","example":"Alteração mental e extremidades frias podem indicar hipoperfusão em certos cenários.","question":"Qual fenômeno é central no choque?","options":["Aumento normal de apetite","Somente febre","Perfusão tecidual inadequada"],"correct":2,"feedback":"Perfusão tecidual inadequada. Choque representa perfusão tecidual inadequada por diferentes mecanismos, como hipovolemia, falha de bomba, obstrução ou vasodilatação. Reconhecer sinais de hipoperfusão e suas causas exige avaliação urgente.","cycle":"internato"},{"id":"urgencia-emergencia-4","name":"Síndrome coronariana aguda","theory":"Síndromes coronarianas agudas são condições tempo-dependentes associadas à isquemia miocárdica. Avaliação clínica, eletrocardiograma e marcadores de lesão são interpretados por equipes treinadas conforme protocolos.","example":"Dor torácica sugestiva com sudorese e dispneia requer atendimento imediato.","question":"Qual órgão está em risco na síndrome coronariana aguda?","options":["Coração","Baço","Pele"],"correct":0,"feedback":"Coração. Síndromes coronarianas agudas são condições tempo-dependentes associadas à isquemia miocárdica. Avaliação clínica, eletrocardiograma e marcadores de lesão são interpretados por equipes treinadas conforme protocolos.","cycle":"internato"},{"id":"urgencia-emergencia-5","name":"Insuficiência respiratória aguda","theory":"Falha de oxigenação, ventilação ou ambas pode causar insuficiência respiratória aguda. Sinais clínicos e medidas de gasometria ou oximetria devem ser integrados ao contexto, sem retardar atendimento.","example":"Dispneia intensa e rebaixamento de consciência são sinais de gravidade.","question":"Qual sistema está diretamente comprometido?","options":["Tegumentar isolado","Respiratório","Esquelético apenas"],"correct":1,"feedback":"Respiratório. Falha de oxigenação, ventilação ou ambas pode causar insuficiência respiratória aguda. Sinais clínicos e medidas de gasometria ou oximetria devem ser integrados ao contexto, sem retardar atendimento.","cycle":"internato"},{"id":"urgencia-emergencia-6","name":"Sepse e reconhecimento","theory":"Sepse é disfunção orgânica potencialmente fatal decorrente de resposta desregulada à infecção. A identificação exige atenção à gravidade, possível foco e medidas protocoladas sob supervisão clínica.","example":"Infecção associada a alteração importante do estado mental pode ser sinal de gravidade.","question":"Qual elemento integra o conceito de sepse?","options":["Toda febre isolada","Colonização sem manifestação","Disfunção orgânica associada a infecção"],"correct":2,"feedback":"Disfunção orgânica associada a infecção. Sepse é disfunção orgânica potencialmente fatal decorrente de resposta desregulada à infecção. A identificação exige atenção à gravidade, possível foco e medidas protocoladas sob supervisão clínica.","cycle":"internato"}]}];
export const medCycles:{value:MedCycle;label:string;description:string}[]=[
{value:"basico",label:"Ciclo básico",description:"Fundamentos morfofuncionais, moleculares e saúde coletiva"},
{value:"clinico",label:"Ciclo clínico",description:"Fisiopatologia, semiologia e integração com situações clínicas"},
{value:"internato",label:"Internato",description:"Cuidado supervisionado, estágios e discussão de situações práticas"}
];
export function getMedDiscipline(slug:string|null|undefined){return medicineDisciplines.find(d=>d.slug===slug)}
export function getMedTopic(discipline:string|null|undefined,id:string|null|undefined){return getMedDiscipline(discipline)?.topics.find(t=>t.id===id)}
